import java.util.*;

class Solution {
    public long countSubarraysWithSumK(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        count.put(0, 1);
        int sum = 0, answer = 0;
        for (int value : nums) {
            sum += value;
            answer += count.getOrDefault(sum - k, 0);
            count.put(sum, count.getOrDefault(sum, 0) + 1);
        }
        return answer;
    }
}
